-- Questions de lecture, lot 2 : paliers 50 % et 100 % (généré par scripts/quiz-seed-2.js)
delete from public.book_quiz where book_key = 'la verite sur l affaire harry quebert' and tier = 100;
on conflict (book_key, tier) do update set book_title = excluded.book_title, question = excluded.question, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
